export type Recipient = {
  id: string
  name: string
  accountMasked: string
  currency: string
}

export const RECENT_RECIPIENTS: Recipient[] = [
  { id: "r1", name: "Amara Okafor", accountMasked: "•••• 4471", currency: "EUR" },
  { id: "r2", name: "Diego Fernandez", accountMasked: "•••• 8823", currency: "MXN" },
  { id: "r3", name: "Priya Nair", accountMasked: "•••• 1190", currency: "INR" },
  { id: "r4", name: "Tom Whitfield", accountMasked: "•••• 5502", currency: "GBP" },
]

const RATES: Record<string, number> = {
  EUR: 0.92,
  MXN: 17.8,
  INR: 83.1,
  GBP: 0.79,
}

const ARRIVAL: Record<string, string> = {
  EUR: "Usually arrives in a few seconds",
  MXN: "Usually arrives within 1 hour",
  INR: "Usually arrives within 1 business day",
  GBP: "Usually arrives in a few seconds",
}

export type Quote = {
  fee: number
  rate: number
  recipientGets: number
  total: number
  arrival: string
}

export function getQuote(amount: number, currency: string): Quote {
  const rate = RATES[currency] ?? 1
  const fee = amount > 0 ? Math.max(1.5, amount * 0.005) : 0
  const total = amount + fee
  const recipientGets = amount * rate
  return { fee, rate, recipientGets, total, arrival: ARRIVAL[currency] ?? "Usually arrives within 1 business day" }
}

export type SendMoneyData = {
  recipientId: string | null
  recipientName: string
  recipientAccountMasked: string
  recipientCurrency: string
  amount: string
}

export const SEND_MONEY_INITIAL: SendMoneyData = {
  recipientId: null,
  recipientName: "",
  recipientAccountMasked: "",
  recipientCurrency: "",
  amount: "",
}

export const SEND_MONEY_STEPS = ["recipient", "amount", "review"] as const

export type SendMoneyStepProps = {
  data: SendMoneyData
  patch: (p: Partial<SendMoneyData>) => void
  next: () => void
  back: () => void
  goTo: (i: number) => void
}

