"use client"
import { useState } from "react"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { RECENT_RECIPIENTS, type Recipient, type SendMoneyStepProps } from "../schema"

function SearchIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
      <circle cx="7" cy="7" r="5" stroke="currentColor" strokeWidth="1.5" />
      <path d="M11 11L14.5 14.5" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
    </svg>
  )
}

function RecipientRow({ recipient, onSelect }: { recipient: Recipient; onSelect: () => void }) {
  const initials = recipient.name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase()

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault()
      onSelect()
    }
  }

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={onSelect}
      onKeyDown={handleKeyDown}
      style={{
        display: "flex",
        alignItems: "center",
        gap: "var(--atlas-spacing-3)",
        paddingBlock: "var(--atlas-spacing-3)",
        paddingInline: "var(--atlas-spacing-3)",
        borderRadius: "var(--atlas-radius-md)",
        border: "var(--atlas-border-width-1) solid var(--atlas-border)",
        background: "var(--atlas-surface)",
        cursor: "pointer",
      }}
    >
      <div
        aria-hidden="true"
        style={{
          width: "var(--atlas-spacing-10)",
          height: "var(--atlas-spacing-10)",
          borderRadius: "var(--atlas-radius-full)",
          background: "var(--atlas-primary-subtle)",
          color: "var(--atlas-primary)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: "var(--atlas-font-size-sm)",
          fontWeight: "var(--atlas-font-weight-semibold)",
          flexShrink: 0,
        }}
      >
        {initials}
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-0_5)", flex: 1, minWidth: 0 }}>
        <span
          style={{
            fontSize: "var(--atlas-text-body)",
            fontWeight: "var(--atlas-font-weight-medium)",
            color: "var(--atlas-foreground)",
          }}
        >
          {recipient.name}
        </span>
        <span style={{ fontSize: "var(--atlas-text-caption)", color: "var(--atlas-foreground-muted)" }}>
          {recipient.accountMasked}
        </span>
      </div>
      <Badge variant="secondary" size="sm">
        {recipient.currency}
      </Badge>
    </div>
  )
}

export function RecipientStep({ patch, next }: SendMoneyStepProps) {
  const [query, setQuery] = useState("")
  const filtered = RECENT_RECIPIENTS.filter((r) => r.name.toLowerCase().includes(query.toLowerCase()))

  const select = (recipient: Recipient) => {
    patch({
      recipientId: recipient.id,
      recipientName: recipient.name,
      recipientAccountMasked: recipient.accountMasked,
      recipientCurrency: recipient.currency,
    })
    next()
  }

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-4)",
        paddingInline: "var(--atlas-spacing-4)",
      }}
    >
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <Label htmlFor="recipient-search" size="sm">
          Search recipients
        </Label>
        <Input
          id="recipient-search"
          type="search"
          placeholder="Name or account"
          leadingIcon={<SearchIcon />}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-2)" }}>
        <span
          style={{
            fontSize: "var(--atlas-text-caption)",
            fontWeight: "var(--atlas-font-weight-medium)",
            color: "var(--atlas-foreground-muted)",
          }}
        >
          Recent recipients
        </span>
        {filtered.map((recipient) => (
          <RecipientRow key={recipient.id} recipient={recipient} onSelect={() => select(recipient)} />
        ))}
        {filtered.length === 0 && (
          <span style={{ fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }}>
            No recipients match “{query}”.
          </span>
        )}
      </div>
    </div>
  )
}

